<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sayfa düzenle</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:850px;margin:35px auto;padding:0 18px}.panel{background:white;padding:24px;border-radius:14px}label{display:block;margin:15px 0;font-weight:700;font-size:13px}input,textarea,select{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;font:inherit}textarea{min-height:300px}.btn{background:#176b50;color:white;border:0;padding:13px 18px;border-radius:8px;font-weight:700}</style></head><body><main class="wrap"><h1><?= !empty($page['id'])?'Sayfayı düzenle':'Yeni sayfa' ?></h1><form method="post" action="/admin/pages/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($page['id']??0) ?>"><section class="panel"><label>Sayfa başlığı<input name="title" required maxlength="220" value="<?= e($page['title']??'') ?>"></label><label>URL kısa adı<input name="slug" required maxlength="240" value="<?= e($page['slug']??'') ?>"></label><label>Yayın durumu<select name="status"><option value="draft" <?= ($page['status']??'draft')==='draft'?'selected':'' ?>>Taslak</option><option value="published" <?= ($page['status']??'')==='published'?'selected':'' ?>>Yayında</option></select></label><label>İçerik<textarea name="content" required><?= e($page['content']??'') ?></textarea></label><button class="btn">Kaydet</button></section></form><p><a href="/admin/pages">Sayfalara dön</a></p></main></body></html>